from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda c: sum(v == c for row in grid for v in row))
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r,c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            comp = []
            outside = False
            while q:
                y,x = q.popleft()
                comp.append((y,x))
                if y == 0 or x == 0 or y == h-1 or x == w-1:
                    outside = True
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx = y+dy,x+dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == bg and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            if not outside:
                ys = [y for y, x in comp]
                xs = [x for y, x in comp]
                # Even-sided square cavities are colored 2; all others 7.
                bh = max(ys) - min(ys) + 1
                bw = max(xs) - min(xs) + 1
                fill = 2 if bh == bw and bh % 2 == 0 else 7
                for y,x in comp:
                    out[y][x] = fill
    return out
